def analyze(d):
    O=G[f'Demo pair {d} output']; I=G[f'Demo pair {d} input']
    B=[I[3*b:3*b+3] for b in range(4)]
    # For each out cell, gather source colors under vertical band shifts o, no horiz shift, later bands overwrite
    # Rule: cell = last nonzero band among those covering this row after shift
    best=None
    for oo in itertools.product(range(3),repeat=4):
        P=[[0]*6 for _ in range(3)]
        for b in range(4):
            for rr in range(3):
                sr=oo[b]+rr
                if sr<3:
                    for c in range(6):
                        v=B[b][rr][c]
                        if v: P[sr][c]=v
        mism=sum(1 for r in range(3) for c in range(6) if P[r][c]!=O[r][c])
        if best is None or mism<best[0]: best=(mism,list(P),''.join(map(' '.join,map(str,O)))[:70])
    return best
for d in range(1,7): print(d,analyze(d)[:2])

import os,glob,re
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))

